    skLineSegment(s1, "line4", { "start" : vector(10, 17.320508) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(s1);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "s1"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    fillet(context, id + "fillet1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(0, 0, 5) * millimeter), "crossSection" : FilletCrossSection.CURVATURE, "nonCircularRadius" : 4 * millimeter, "magnitude" : 0.975 });
